def coerce_record(record: dict, schema: dict) -> dict:
    out = dict(record)
    for k, target in schema.items():
        if k not in out or out[k] is None:
            continue
        val = out[k]
        if target == "int":
            out[k] = int(val)
        elif target == "float":
            out[k] = float(val)
        elif target == "str":
            out[k] = str(val)
        elif target == "bool":
            if isinstance(val, bool):
                out[k] = val
            elif isinstance(val, str):
                out[k] = val.strip().lower() in {"true", "1", "yes"}
            else:
                out[k] = bool(val)
    return out

