questions.reference_solution:
def calculate_progressive_tax(income: float, brackets: list) -> float:
    if income <= 0:
        return 0.0
    tax = 0.0
    prev = 0.0
    for limit, rate in brackets:
        if income <= prev:
            break
        upper = income if limit is None else min(income, limit)
        taxable = max(0.0, upper - prev)
        tax += taxable * rate
        if limit is None:
            break
        prev = limit
    return round(tax, 2)

