def run_length_encode(text: str) -> str:
    if not text:
        return ""
    parts = []
    curr = text[0]
    count = 1
    for ch in text[1:]:
        if ch == curr:
            count += 1
        else:
            parts.append(f"{curr}{count}")
            curr = ch
            count = 1
    parts.append(f"{curr}{count}")
    return "".join(parts)

