def simulate_retries(outcomes: list, max_retries: int, base_delay: float, max_delay: float) -> list:
    total_wait = 0.0
    attempts = 0
    limit = min(len(outcomes), 1 + max_retries)
    for idx in range(limit):
        attempts += 1
        if outcomes[idx]:
            return [True, attempts, round(total_wait, 6)]
        if idx < limit - 1:
            delay = min(max_delay, base_delay * (2 ** idx))
            total_wait += delay
    return [False, attempts, round(total_wait, 6)]

