questions.reference_solution:
def compare_semver(v1: str, v2: str) -> int:
    def parse(v: str) -> list:
        return [int(x) for x in v.strip().lstrip("vV").split(".") if x]
    p1, p2 = parse(v1), parse(v2)
    max_len = max(len(p1), len(p2))
    p1 += [0] * (max_len - len(p1))
    p2 += [0] * (max_len - len(p2))
    if p1 < p2:
        return -1
    if p1 > p2:
        return 1
    return 0

