def moving_averages(values: list, k: int) -> list:
    if k <= 0 or len(values) < k:
        return []
    window_sum = sum(values[:k])
    res = [round(window_sum / k, 2)]
    for i in range(k, len(values)):
        window_sum += values[i] - values[i - k]
        res.append(round(window_sum / k, 2))
    return res

