def resolve_effective_permissions(role_perms: dict, role_inherits: dict, assigned_roles: list) -> list:
    visited = set()
    stack = list(assigned_roles)
    perms = set()
    while stack:
        role = stack.pop()
        if role in visited:
            continue
        visited.add(role)
        perms.update(role_perms.get(role, []))
        for parent in role_inherits.get(role, []):
            if parent not in visited:
                stack.append(parent)
    return sorted(perms)

