from collections import OrderedDict

def simulate_lru(capacity: int, ops: list) -> list:
    cache = OrderedDict()
    outputs = []
    for op in ops:
        if op[0] == "GET":
            k = op[1]
            if k not in cache:
                outputs.append(-1)
            else:
                cache.move_to_end(k)
                outputs.append(cache[k])
        elif op[0] == "PUT":
            _, k, v = op
            if k in cache:
                cache.move_to_end(k)
            cache[k] = v
            if len(cache) > capacity:
                cache.popitem(last=False)
    return outputs

