def resolve_relative_import(current_package: str, import_stmt: str) -> str:
    if not import_stmt.startswith("."):
        return import_stmt
    dots = len(import_stmt) - len(import_stmt.lstrip("."))
    remainder = import_stmt[dots:]
    parts = current_package.split(".") if current_package else []
    levels_up = dots - 1
    if levels_up > len(parts):
        raise ImportError("attempted relative import beyond top-level package")
    base = parts[: len(parts) - levels_up]
    if remainder:
        base.append(remainder)
    return ".".join(base)

