def has_circular_import(imports: dict) -> bool:
    state = {}  # 1=visiting, 2=done

    def dfs(node: str) -> bool:
        st = state.get(node, 0)
        if st == 1:
            return True
        if st == 2:
            return False
        state[node] = 1
        for dep in imports.get(node, []):
            if dfs(dep):
                return True
        state[node] = 2
        return False

    return any(dfs(mod) for mod in list(imports.keys()))

