    act = parse(actual_freeze)
    return {
        "missing": sorted(exp.keys() - act.keys()),
        "extra": sorted(act.keys() - exp.keys()),
        "mismatched": {k: [exp[k], act[k]] for k in sorted(exp.keys() & act.keys()) if exp[k] != act[k]},
