import re

def satisfies_spec(version: str, spec: str) -> bool:
    def ver_tuple(v: str) -> tuple:
        parts = [int(x) for x in v.strip().split(".")]
        while len(parts) < 3:
            parts.append(0)
        return tuple(parts)

    v = ver_tuple(version)
    for clause in [c.strip() for c in spec.split(",") if c.strip()]:
        m = re.match(r"^(==|!=|>=|<=|>|<)\s*(.+)$", clause)
        if not m:
            raise ValueError(f"Invalid specifier: {clause}")
        op, target = m.group(1), ver_tuple(m.group(2))
        ok = {
            "==": v == target,
            "!=": v != target,
            ">=": v >= target,
            "<=": v <= target,
            ">": v > target,
            "<": v < target,
        }[op]
        if not ok:
            return False
    return True

