def rotate_logs(log_path: str, max_backups: int) -> None:
    base = Path(log_path)
    if max_backups >= 1:
        oldest = Path(f"{base}.{max_backups}")
        if oldest.exists():
            oldest.unlink()
        for i in range(max_backups, 1, -1):
            src = Path(f"{base}.{i - 1}")
