def ttl_cache(ttl_seconds: float, clock=time.monotonic):
    def decorator(fn):
        cache = {}
        @wraps(fn)
        def wrapper(*args):
            now = clock()
            if args in cache:
                ts, val = cache[args]
                if now - ts < ttl_seconds:
                    return val
            val = fn(*args)
            cache[args] = (now, val)
            return val
        return wrapper
    return decorator

