        return type(self)(self.title, self.sections)

    def __deepcopy__(self, memo):
        if id(self) in memo:
            return memo[id(self)]
        cloned = type(self).__new__(type(self))
        memo[id(self)] = cloned
        cloned.title = copy.deepcopy(self.title, memo)
        cloned.sections = copy.deepcopy(self.sections, memo)
        return cloned

