import threading

def process_via_queue(items: list, num_workers: int = 2) -> list:
    q = queue.Queue()
    results = []
    lock = threading.Lock()

    def worker():
        while True:
            item = q.get()
            try:
                if item is None:
                    return
                sq = item * item
                with lock:
                    results.append(sq)
            finally:
                q.task_done()

    threads = [threading.Thread(target=worker) for _ in range(num_workers)]
    for t in threads:
        t.start()
    for x in items:
        q.put(x)
    for _ in range(num_workers):
        q.put(None)
    q.join()
    for t in threads:
        t.join()
    return sorted(results)

import threading

def coordinated_start(num_workers: int) -> list:
    ready = threading.Event()
    shared = {"phase": "INIT"}
    seen = []
    lock = threading.Lock()

    def worker():
        if ready.wait(timeout=2.0):
            with lock:
                seen.append(shared["phase"])

    threads = [threading.Thread(target=worker) for _ in range(num_workers)]
    for t in threads:
        t.start()
    shared["phase"] = "GO"
    ready.set()
    for t in threads:
        t.join()
    return [shared["phase"], len([x for x in seen if x == "GO"])]

