import threading

class BoundedBuffer:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self._buf = []
        self._cond = threading.Condition()

    def put(self, item) -> None:
        with self._cond:
            while len(self._buf) >= self.capacity:
                self._cond.wait()
            self._buf.append(item)
            self._cond.notify_all()

    def get(self):
        with self._cond:
            while not self._buf:
                self._cond.wait()
            item = self._buf.pop(0)
            self._cond.notify_all()
            return item

