import sys

def count_executed_lines(fn, *args):
    lines = set()
    target_code = fn.__code__

    def tracer(frame, event, arg):
        if frame.f_code is target_code and event == "line":
            lines.add(frame.f_lineno)
        return tracer

    prev = sys.gettrace()
    sys.settrace(tracer)
    try:
        result = fn(*args)
    finally:
        sys.settrace(prev)
    return (result, len(lines))

