import time

def assert_within_budget(fn, max_ms: float, *args):
    t0 = time.perf_counter()
    result = fn(*args)
    elapsed_ms = (time.perf_counter() - t0) * 1000.0
    if elapsed_ms > max_ms:
        raise AssertionError(f"Exceeded budget: {elapsed_ms:.2f}ms > {max_ms}ms")
    return (result, round(elapsed_ms, 2))

