questions.reference_solution:
def parse_docstring(doc: str) -> dict:
    summary_lines = []
    args = {}
    returns_lines = []
    section = "summary"
    for raw in doc.strip().splitlines():
        line = raw.strip()
        if not line:
            continue
        if line == "Args:":
            section = "args"
            continue
        if line == "Returns:":
            section = "returns"
            continue
        if section == "summary":
            summary_lines.append(line)
        elif section == "args" and ":" in line:
            left, desc = line.split(":", 1)
            arg_name = left.split("(")[0].strip()
            args[arg_name] = desc.strip()
        elif section == "returns":
            returns_lines.append(line)
    return {
        "summary": " ".join(summary_lines),
        "args": args,
        "returns": " ".join(returns_lines),
    }

