import ast

def find_untyped_functions(code: str) -> list:
    tree = ast.parse(code)
    missing = []
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            params = node.args.posonlyargs + node.args.args + node.args.kwonlyargs
            missing_param = any(
                a.annotation is None for a in params if a.arg not in {"self", "cls"}
            )
            if node.returns is None or missing_param:
                missing.append(node.name)
    return sorted(set(missing))

