import cProfile
import pstats

def find_most_called_func(target_fn) -> str:
    pr = cProfile.Profile()
    pr.enable()
    try:
        target_fn()
    finally:
        pr.disable()
    ps = pstats.Stats(pr)
    candidates = [
        (vals[1], key[2])
        for key, vals in ps.stats.items()
        if key[0] != "~" and not key[2].startswith("<")
    ]
    if not candidates:
        return ""
    return max(candidates, key=lambda item: item[0])[1]

