questions.reference_solution:
class Container:
    def __init__(self):
        self._providers = {}
        self._singletons = {}

    def register(self, key, factory, singleton: bool = False) -> None:
        self._providers[key] = (factory, singleton)
        self._singletons.pop(key, None)

    def resolve(self, key):
        if key not in self._providers:
            raise KeyError(f"Unregistered dependency: {key!r}")
        factory, is_singleton = self._providers[key]
        if is_singleton:
            if key not in self._singletons:
                self._singletons[key] = factory(self)
            return self._singletons[key]
        return factory(self)
